                      select(dep_delay, origin) |&gt; 
                      filter(origin == "JFK") |&gt; 
                      drop_na() |&gt; 
                      sample_n(size = sample_size) |&gt; 
                      summarise(dep_delay = mean(dep_delay))) |&gt; 
  as.numeric() |&gt; 
  mean()

